import{_ as t,o as e,c as r,a4 as o}from"./chunks/framework.9tZL7ZIQ.js";const c=JSON.parse('{"title":"2025年 核心总结","description":"","frontmatter":{},"headers":[],"relativePath":"01_letters/2025年/核心总结.md","filePath":"01_letters/2025年/核心总结.md"}'),l={name:"01_letters/2025年/核心总结.md"};function n(s,a,i,h,d,_){return e(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="_2025年-核心总结" tabindex="-1">2025年 核心总结 <a class="header-anchor" href="#_2025年-核心总结" aria-label="Permalink to &quot;2025年 核心总结&quot;">​</a></h1><h2 id="年度业绩" tabindex="-1">年度业绩 <a class="header-anchor" href="#年度业绩" aria-label="Permalink to &quot;年度业绩&quot;">​</a></h2><p>2025年是巴菲特致股东信的告别篇。巴菲特宣布将卸任伯克希尔·哈撒韦掌舵人之位，推荐格雷格·阿贝尔（Greg Abel）接任 CEO，自己仅通过每年感恩节寄语与股东保持联系。同日，巴菲特将1800股A股转换为270万股B股，捐赠给四家家族基金会（苏珊·汤普森·巴菲特基金会150万股，其余三家各40万股）。</p><hr><h2 id="告别寄语-追忆与感恩" tabindex="-1">告别寄语：追忆与感恩 <a class="header-anchor" href="#告别寄语-追忆与感恩" aria-label="Permalink to &quot;告别寄语：追忆与感恩&quot;">​</a></h2><p>巴菲特罕见地以个人叙事方式回顾一生：1938年童年阑尾炎住院经历、与修女们的温馨互动、姨妈的指纹采集礼物。感恩节寄语中，巴菲特回顾了他人生中的几位重要人物——<strong>查理·芒格</strong>（64年挚友与导师）、<strong>斯坦·利普西</strong>（水牛城新闻CEO）、<strong>小沃尔特·斯科特</strong>（中美能源创始人、前董事）、<strong>唐·基奥</strong>（可口可乐前总裁）。</p><hr><h2 id="格雷格·阿贝尔-greg-abel-接任" tabindex="-1">格雷格·阿贝尔（Greg Abel）接任 <a class="header-anchor" href="#格雷格·阿贝尔-greg-abel-接任" aria-label="Permalink to &quot;格雷格·阿贝尔（Greg Abel）接任&quot;">​</a></h2><p>巴菲特明确表示：格雷格·阿贝尔将在2025年末正式接任 CEO。阿贝尔是加拿大籍，1990年代已在奥马哈法拉姆街居住，彼时距巴菲特家仅几个街区。巴菲特评价他&quot;卓越的管理者、不知疲倦的实干者、坦诚的沟通者&quot;。</p><hr><h2 id="人物深度追忆" tabindex="-1">人物深度追忆 <a class="header-anchor" href="#人物深度追忆" aria-label="Permalink to &quot;人物深度追忆&quot;">​</a></h2><ul><li><strong>查理·芒格</strong>：1930年代曾在巴菲特祖父的杂货店打工，1940年一天赚2美元。哈佛法学院毕业后定居加州，1959年才与巴菲特正式见面。64年搭档，从未争吵，互相影响深远</li><li><strong>斯坦·利普西</strong>：1968年将奥马哈太阳报卖给伯克希尔，1978年搬到布法罗，帮助打造水牛城周日报纸，3300万美元投资实现年化100%+税前回报</li><li><strong>小沃尔特·斯科特</strong>：1999年将中美能源带入伯克希尔，生前是备受敬重的董事，奥马哈慈善领袖</li><li><strong>唐·基奥</strong>：巴菲特邻居之子，从咖啡推销员做到可口可乐总裁，1985年&quot;新可乐&quot;危机中的认错演讲成经典公关案例</li></ul><hr><h2 id="核心投资理念" tabindex="-1">核心投资理念 <a class="header-anchor" href="#核心投资理念" aria-label="Permalink to &quot;核心投资理念&quot;">​</a></h2><p>巴菲特再次强调奥马哈对他的塑造：1956年离开纽约回到奥马哈，再未离开。&quot;奥马哈的水里有魔力吗？&quot;——这是巴菲特的反问，也是对价值投资本土根源的自问。</p><hr><h2 id="历史意义" tabindex="-1">历史意义 <a class="header-anchor" href="#历史意义" aria-label="Permalink to &quot;历史意义&quot;">​</a></h2><p>这是巴菲特真正意义上的&quot;告别信&quot;。伯克希尔·哈撒韦从一家纺织厂，成长为市值超万亿美元的超级投资旗舰。巴菲特从27岁创业到95岁退休，创造了人类商业史上绝无仅有的记录。他的退出，标志着价值投资一个时代的落幕。</p>',18)])])}const g=t(l,[["render",n]]);export{c as __pageData,g as default};
